        "exam_code": "SU26_RE",
        "content": "ELC201_SU26_RE • Multiple Choice\n\n(Choose 1 answer)\n\nRefer to the given figure. The voltage gain of this amplifier is\n\n[Schematic diagram of a non-inverting operational amplifier. The non-inverting input ($+$) is connected to $V_{in}$. The inverting input ($-$) is connected to a feedback resistor $R_f = 100\\text{ k}\\Omega$ from the output $V_{out}$, and to ground through a resistor $R_i = 5\\text{ k}\\Omega$.]",
