        "exam_source": "Đề 2 (SU26 RE)",
        "exam_code": "SU26_RE",
        "content": "ELC201_SU26_RE • Multiple Choice\n\n(Choose 1 answer)\n\nIn the common-emitter configuration, the current gain ( $\\beta$ ) is defined as:",
